#!/usr/bin/env bash
# Create .env (git-ignored) with generated secrets. Never overwrites an existing file.
set -euo pipefail
cd "$(dirname "$0")/.."
if [[ -f .env ]]; then
  echo ".env already exists - keeping it."
  exit 0
fi
gen_key() { python3 -c 'import base64,os;print(base64.urlsafe_b64encode(os.urandom(32)).decode())'; }
cat > .env <<EOF
# Generated by scripts/make_env.sh on $(date -Iseconds). Keep this file private.
HOST_UID=$(id -u)
HOST_GID=$(id -g)
ADMIN_TOKEN=$(python3 -c 'import secrets;print(secrets.token_urlsafe(24))')
FEEDBACK_ENCRYPTION_KEY=$(gen_key)
GRAFANA_ADMIN_PASSWORD=$(python3 -c 'import secrets;print(secrets.token_urlsafe(12))')
RETRAIN_COOLDOWN_SECONDS=1800
DRIFT_WINDOW=200
DRIFT_MIN_SAMPLES=50
# Leave empty to auto-detect from the browser address (http://<host>:8000).
API_BASE_URL=
CORS_ORIGINS=*
EOF
chmod 600 .env
echo "Created .env (admin token + encryption key generated)."
grep ADMIN_TOKEN .env
